def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    out=[[bg]*w for _ in range(h)]
    # Find near-solid rectangles. The sparse non-background cells inside them
    # are speckle occlusions; isolated marks are excluded by the minimum area.
    candidates=[]
    colors=set(x for row in grid for x in row if x!=bg)
    for color in colors:
        for r0 in range(h):
            for r1 in range(r0+1,h):
                for c0 in range(w):
                    for c1 in range(c0+1,w):
                        area=(r1-r0+1)*(c1-c0+1)
                        if area<4: continue
                        n=sum(grid[r][c]==color for r in range(r0,r1+1) for c in range(c0,c1+1))
                        if n>=4 and n/area>=0.72:
                            candidates.append((n/area,area,n,r0,c0,r1,c1,color))
    candidates.sort(key=lambda x:(x[1],x[0],x[2]), reverse=True)
    for density,area,n,r0,c0,r1,c1,color in candidates:
        # Do not let a lower-confidence candidate overwrite another object.
        if any(out[r][c]!=bg for r in range(r0,r1+1) for c in range(c0,c1+1)):
            continue
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): out[r][c]=color
    return out
